import{_ as n,o as e,c as r,a3 as i}from"./chunks/framework.BvvarXmc.js";const m=JSON.parse('{"title":"Rekap Laporan Keuangan & Tunggakan Siswa","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-keuangan/laporan-keuangan.md","filePath":"panduan-keuangan/laporan-keuangan.md","lastUpdated":null}'),l={name:"panduan-keuangan/laporan-keuangan.md"};function t(s,a,o,u,g,k){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="rekap-laporan-keuangan-tunggakan-siswa" tabindex="-1">Rekap Laporan Keuangan &amp; Tunggakan Siswa <a class="header-anchor" href="#rekap-laporan-keuangan-tunggakan-siswa" aria-label="Permalink to &quot;Rekap Laporan Keuangan &amp; Tunggakan Siswa&quot;">​</a></h1><p>Bendahara dapat mencetak dan mengekspor berbagai laporan keuangan secara realtime untuk pelaporan ke Kepala Sekolah atau Yayasan.</p><hr><h2 id="_1-rekap-penerimaan-kas-harian-bulanan" tabindex="-1">1. Rekap Penerimaan Kas Harian / Bulanan <a class="header-anchor" href="#_1-rekap-penerimaan-kas-harian-bulanan" aria-label="Permalink to &quot;1. Rekap Penerimaan Kas Harian / Bulanan&quot;">​</a></h2><ol><li>Buka menu <strong>Keuangan</strong> <strong>Laporan (Reports)</strong> <strong>Penerimaan Kas</strong>.</li><li>Tentukan rentang tanggal (misal: <em>1 Oktober 2026 s/d 31 Oktober 2026</em>).</li><li>Pilih sumber transaksi: <ul><li>Semua Sumber</li><li>Hanya Loket Kasir (Tunai)</li><li>Hanya Online (Virtual Account Bank)</li></ul></li><li>Klik tombol <strong>Tampilkan Laporan</strong>.</li><li>Layar akan menampilkan rincian total dana terkumpul per pos pembayaran (Total SPP, Total Uang Gedung, dll.).</li><li>Klik tombol <strong>Ekspor Excel</strong> atau <strong>Cetak PDF</strong>.</li></ol><hr><h2 id="_2-memantau-mengekspor-daftar-tunggakan-siswa" tabindex="-1">2. Memantau &amp; Mengekspor Daftar Tunggakan Siswa <a class="header-anchor" href="#_2-memantau-mengekspor-daftar-tunggakan-siswa" aria-label="Permalink to &quot;2. Memantau &amp; Mengekspor Daftar Tunggakan Siswa&quot;">​</a></h2><p>Untuk mengetahui siswa mana saja yang belum melunasi kewajiban keuangannya:</p><ol><li>Buka menu <strong>Laporan</strong> <strong>Rekap Tunggakan</strong>.</li><li>Pilih filter: <ul><li>Berdasarkan Tingkat / Kelas (misal: <em>Kelas XII Semua Jurusan</em>).</li><li>Berdasarkan Jenis Tagihan (misal: <em>Hanya SPP</em>).</li></ul></li><li>Klik <strong>Cari Data</strong>.</li><li>Sistem menampilkan tabel siswa, jumlah bulan yang menunggak, dan total rupiah yang belum dibayarkan.</li><li>Anda dapat mengunduh daftar ini ke file <strong>Excel</strong> untuk bahan tindak lanjut wali kelas, atau klik <strong>Kirim Notifikasi Pengingat WhatsApp Masal</strong> ke nomor orang tua siswa yang menunggak.</li></ol>',9)])])}const d=n(l,[["render",t]]);export{m as __pageData,d as default};
